 void syncUI(String host,int port)throws Exception {
  Monitor m=activity.monitor;State initial=m.state;
  Block amp=initial.blocks.stream().filter(b->b.slot==0&&m.model(b)!=null&&m.model(b).category.equals("amp")).findFirst().orElse(initial.blocks.get(0));
  Block delay=initial.blocks.stream().filter(b->b.slot==0&&m.model(b)!=null&&Arrays.asList("delay","reverb").contains(m.model(b).category)).findFirst().orElse(initial.blocks.get(initial.blocks.size()-1));
  require(!(amp.path==delay.path&&amp.pos==delay.pos),"Need two block locations");
  Session external=new Session(new File(getTargetContext().getCacheDir(),"selection-check"));external.connect(host,port);
  Thread listener=new Thread(()->{try{while(!external.closed)external.event();}catch(Exception ignored){}});listener.setDaemon(true);listener.start();
  try {
   for(Block block:new Block[]{amp,delay}){
    State source=external.snapshot();Block target=source.block(block.path,block.pos,block.slot);external.selectBlock(new Models.Context(source,target));
    await(()->m.block()!=null&&m.path==block.path&&m.pos==block.pos&&m.block().model==block.model,"External selection updates native editor "+m.name(block));
    check(m.category.equals(m.model(block).group()),"External selection highlights its model category");
    screen("sync-external-"+block.pos);
   }
   for(Block block:new Block[]{amp,delay}){
    runOnMainSync(()->m.selectLocal(m.state.block(block.path,block.pos,block.slot)));
    await(()->!m.busy&&m.status.equals("Block selected on Stadium")&&m.path==block.path&&m.pos==block.pos,"Tablet selection confirmed by native pedal echo "+m.name(block));
   }
   check(Session.blocksEqual(initial,m.state)&&initial.id==m.state.id&&initial.scene==m.state.scene&&initial.dirty==m.state.dirty,"Selection leaves preset/parameters/dirty state unchanged");
   screen("sync-final");
  }finally{external.close();}
 }
